package com.hostel.hostelmanagement.controller; import com.hostel.hostelmanagement.entity.Room; import com.hostel.hostelmanagement.repository.RoomRepository; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/rooms") public class RoomController {final RoomRepository r;public RoomController(RoomRepository r){this.r=r;}@GetMapping Object all(){return r.findAll();}@PostMapping Room add(@RequestBody Room x){return r.save(x);}@DeleteMapping("/{id}") void del(@PathVariable Long id){r.deleteById(id);}}